127	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
128	    @Override
129	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
130	        List<String> missingFields = new ArrayList<>();
131	        requireNonBlank(missingFields, "firstName", ownerFieldsDto.getFirstName());
132	        requireNonBlank(missingFields, "lastName", ownerFieldsDto.getLastName());
133	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
134	        requireNonBlank(missingFields, "address", normalizedAddress);
135	        requireNonBlank(missingFields, "city", ownerFieldsDto.getCity());
136	        requireNonBlank(missingFields, "telephone", ownerFieldsDto.getTelephone());
137	        if (!missingFields.isEmpty()) {
138	            throw new MissingRequiredFieldsException(missingFields);
139	        }
140	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
141	        LocalDate suppliedOrDefaultDate = ownerFieldsDto.getRegistrationDate() != null
142	            ? ownerFieldsDto.getRegistrationDate() : LocalDate.now();
143	        LocalDate registrationDate = toBusinessDay(suppliedOrDefaultDate);
144	        requireDailyLimitNotReached(registrationDate);
145	        requireCityBelowCapacity(ownerFieldsDto.getCity());
146	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
147	        ownerFieldsDto.setTelephone(normalizedTelephone);
148	        if (ownerFieldsDto.getEmail() != null) {
149	            ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
150	        }
151	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
152	        HttpHeaders headers = new HttpHeaders();
153	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
154	        owner.setAddress(normalizedAddress);
155	        owner.setRegistrationDate(registrationDate);
156	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
157	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
158	        if (sharesHousehold) {
159	            owner.setHouseholdId(householdIdFor(normalizeForHousehold(owner.getLastName()),
160	                householdAddressKey(owner.getAddress())));
161	        }
162	        requireUniqueIdentity(owner);
163	        if (sharesHousehold) {
164	            backfillHousehold(owner.getLastName(), owner.getAddress(), owner.getHouseholdId());
165	        }
166	        this.clinicService.saveOwner(owner);
167	        AUDIT.info("Owner created id={} customerCode={} registrationDate={} membershipLevel={}",
168	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
169	            ownerMapper.toMembershipLevel(owner));
170	        OwnerDto ownerDto = toOwnerDtoWithBulkWarning(owner);
171	        headers.setLocation(UriComponentsBuilder.newInstance()
172	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
173	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
174	    }
