269	    /**
270	     * Builds the owner's customer code as {@code '<CITY3>-<LAST3>-<NNNN>'}, where {@code CITY3} is the
271	     * upper-cased first three letters of {@code city}, {@code LAST3} the upper-cased first three letters
272	     * of {@code lastName}, and {@code NNNN} a per-city 4-digit zero-padded sequence equal to one more
273	     * than the number of owners already in that city (e.g. {@code SYD-SMI-0007}).
274	     *
275	     * @param city the owner's city (already validated non-blank)
276	     * @param lastName the owner's last name (already validated non-blank)
277	     * @return the formatted customer code for the owner being created
278	     */
279	    private String nextCustomerCode(String city, String lastName) {
280	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
281	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
282	        int sequence = (int) this.clinicService.findAllOwners().stream()
283	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
284	            .count() + 1;
285	        return String.format("%s-%s-%04d", city3, last3, sequence);
286	    }
287	
288	    /**
289	     * Counts the existing owners (those already persisted before this create) whose first and last
290	     * names both match the incoming owner's, compared case-insensitively. This snapshot is stored on
291	     * the new owner as its {@code namesakeCount} and echoed back on reads.
292	     *
293	     * @param firstName the incoming owner's first name (already validated non-blank)
294	     * @param lastName the incoming owner's last name (already validated non-blank)
295	     * @return the number of existing namesakes sharing both names case-insensitively
296	     */
297	    private int countNamesakes(String firstName, String lastName) {
298	        return (int) this.clinicService.findAllOwners().stream()
299	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
300	                && lastName.equalsIgnoreCase(existing.getLastName()))
301	            .count();
302	    }
