304	    /**
305	     * Records {@code fieldName} as missing when {@code value} is {@code null} or blank (empty or
306	     * whitespace-only), so the caller can reject the request listing every offending field.
307	     */
308	    private static void requireNonBlank(List<String> missingFields, String fieldName, String value) {
309	        if (value == null || value.isBlank()) {
310	            missingFields.add(fieldName);
311	        }
312	    }
