314	    /**
315	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets are stripped. When the
316	     * value carries a leading {@code '+'} its country code is kept; otherwise a {@code '+61'} country
317	     * code is assumed and a single leading {@code '0'} is dropped from the national digits. The result
318	     * must be a {@code '+'} followed by 8 to 15 digits. For example {@code "0412 345 678"} becomes
319	     * {@code "+61412345678"}.
320	     *
321	     * @param telephone the raw telephone value from the request
322	     * @return the normalized E.164 telephone number (a {@code '+'} followed by 8 to 15 digits)
323	     * @throws InvalidFieldValueException if the value cannot form a valid E.164 number
324	     */
325	    private static String normalizeTelephone(String telephone) {
326	        String e164 = toE164(telephone);
327	        if (e164 == null) {
328	            throw new InvalidFieldValueException("telephone",
329	                "Telephone must be a valid E.164 number ('+' followed by 8 to 15 digits)");
330	        }
331	        return e164;
332	    }
333	
334	    /**
335	     * Converts a raw telephone value to E.164 form, or returns {@code null} when it cannot form a
336	     * valid E.164 number. Used both to normalize incoming values and to compare against existing
337	     * owners' stored numbers when detecting duplicates.
338	     */
339	    private static String toE164(String telephone) {
340	        if (telephone == null) {
341	            return null;
342	        }
343	        String cleaned = telephone.trim().replaceAll("[\\s\\-()]", "");
344	        String digits;
345	        if (cleaned.startsWith("+")) {
346	            digits = cleaned.substring(1);
347	        } else {
348	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
349	            digits = "61" + national;
350	        }
351	        if (!digits.matches("[0-9]{8,15}")) {
352	            return null;
353	        }
354	        if (!hasValidNationalLength(digits)) {
355	            return null;
356	        }
357	        return "+" + digits;
358	    }
359	
360	    /**
361	     * Checks the national-number length against the country code for the country codes that pin one.
362	     * A {@code '+61'} (Australia) number must carry exactly 9 national digits and a {@code '+1'}
363	     * (NANP) number exactly 10; every other country code is accepted on the general 8-to-15-digit
364	     * rule alone. {@code digits} is the E.164 digit string without the leading {@code '+'}.
365	     */
366	    private static boolean hasValidNationalLength(String digits) {
367	        if (digits.startsWith("61")) {
368	            return digits.length() - 2 == 9;
369	        }
370	        if (digits.startsWith("1")) {
371	            return digits.length() - 1 == 10;
372	        }
373	        return true;
374	    }
