392	    /** The maximum number of owners permitted in a single city; the {@code (50 + 1)}th is rejected. */
393	    private static final int MAX_OWNERS_PER_CITY = 50;
394	
395	    /**
396	     * Rejects the request when the owner's city already contains {@link #MAX_OWNERS_PER_CITY} or more
397	     * owners, comparing city names case-insensitively (consistent with the per-city customer-code
398	     * sequence). Callers reach this only once {@code city} has been validated non-blank.
399	     *
400	     * @param city the incoming owner's city (already validated non-blank)
401	     * @throws CityAtCapacityException if the city is already at or above its owner capacity
402	     */
403	    /** The maximum number of owners that may be registered in a single day; the {@code (100 + 1)}th is rejected. */
404	    private static final int MAX_OWNERS_PER_DAY = 100;
405	
406	    /**
407	     * Rejects the request when {@link #MAX_OWNERS_PER_DAY} or more owners have already been registered
408	     * on {@code businessDay}, counting existing owners whose {@code registrationDate} equals that date.
409	     * New owners take {@code businessDay} as their {@code registrationDate} (the supplied or defaulted
410	     * date rolled forward to a business day), so this caps the number that may be created per day.
411	     *
412	     * @param businessDay the adjusted business-day registration date of the owner being created
413	     * @throws DailyOwnerLimitException if the daily owner-creation limit has already been reached
414	     */
415	    /**
416	     * The number of owners for a single day beyond which the {@code bulkSignupWarning} flag is
417	     * raised; the warning is true once <em>more than</em> this many owners share a registration date.
418	     */
419	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
420	
421	    /**
422	     * Maps {@code owner} to its DTO and sets the {@code bulkSignupWarning} flag: {@code true} when
423	     * more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created for this
424	     * owner's registration date, otherwise {@code false}.
425	     *
426	     * @param owner the owner to map
427	     * @return the owner DTO with its bulk-signup warning flag populated
428	     */
429	    private OwnerDto toOwnerDtoWithBulkWarning(Owner owner) {
430	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
431	        ownerDto.setBulkSignupWarning(exceedsBulkSignupThreshold(owner.getRegistrationDate()));
432	        return ownerDto;
433	    }
434	
435	    /**
436	     * Returns whether more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been
437	     * created on {@code registrationDate}, counting existing owners whose {@code registrationDate}
438	     * equals that date. Returns {@code false} when {@code registrationDate} is {@code null}.
439	     */
440	    private boolean exceedsBulkSignupThreshold(LocalDate registrationDate) {
441	        if (registrationDate == null) {
442	            return false;
443	        }
444	        long registeredThatDay = this.clinicService.findAllOwners().stream()
445	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
446	            .count();
447	        return registeredThatDay > BULK_SIGNUP_WARNING_THRESHOLD;
448	    }
449	
450	    private void requireDailyLimitNotReached(LocalDate businessDay) {
451	        long registeredThatDay = this.clinicService.findAllOwners().stream()
452	            .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
453	            .count();
454	        if (registeredThatDay >= MAX_OWNERS_PER_DAY) {
455	            throw new DailyOwnerLimitException(MAX_OWNERS_PER_DAY);
456	        }
457	    }
458	
459	    /**
460	     * Rolls {@code date} forward to a business day: when it falls on a Saturday or Sunday it advances
461	     * to the following Monday; a weekday is returned unchanged. Applied to the effective registration
462	     * date (whether supplied in the request or defaulted to the server date) so a weekend registration
463	     * is recorded on the next business day, and every value derived from the registration date uses the
464	     * adjusted date.
465	     *
466	     * @param date the effective registration date (supplied or defaulted), never {@code null}
467	     * @return the same date, or the next Monday when {@code date} is a weekend
468	     */
469	    private static LocalDate toBusinessDay(LocalDate date) {
470	        DayOfWeek day = date.getDayOfWeek();
471	        if (day == DayOfWeek.SATURDAY) {
472	            return date.plusDays(2);
473	        }
474	        if (day == DayOfWeek.SUNDAY) {
475	            return date.plusDays(1);
476	        }
477	        return date;
478	    }
